INSERT INTO `chat_messages` (`id`, `user_id`, `question`, `answer`, `created_at`) VALUES (1,2,'Còn hàng không?','Xin lỗi, tôi không tìm thấy sản phẩm phù hợp. Bạn cần giúp tôi mua laptop nào?','2026-06-17 11:36:26'),(2,2,'Laptop gaming dưới 20M','Laptop Msi Gaming LEOPARD GL65 dưới 20 triệu đồng. Laptops MSI Cyborg 15 A13UC-2082VN và MSI Cyborg 15 B13WEKG-676VN (i5-13420H) (Đen) đều phù hợp với nhu cầu của khách hàng.','2026-06-18 05:29:55'),(3,2,'Tìm cho tôi laptop gaming','Laptop gaming chính là Msi Gaming LEOPARD GL65 với giá 118 triệu đồng. Bạn có thể mua được tại Alibaba.com.','2026-06-18 05:30:21'),(4,2,'Còn hàng không?','Đúng, còn hàng. Chúng tôi có các sản phẩm khác như: CARD MÀN HÌNH MSI GTX 1070TI GAMING X 8G, Bộ máy tính Gaming MSI, và VGA MSI GeForce RTX 5060 Ti 8GB VENTUS 3X OC - Card màn hình Chính Hãng. Bạn có thể tham khảo thêm các sản phẩm này để tìm kiếm lại hàng không?','2026-06-18 05:43:57'),(5,2,'Laptop học tập','Laptop MSI Cyborg 15 B13WEKG-676VN (i5-13420H) (Đen) - 28120300.00 Vị trí: Bảo hành 24 tháng\nLaptop MSI Cyborg 15 A13UC-2082VN i7-13620H - RAM 16GB - 512GB SSD - RTX 3050 - 22 sản phẩm còn hàng\nLaptop MSI Gaming LEOPARD GL65 CORE I7 10750H RAM 16G SSD 512G 15.6INCH 144HZ GTX 1650 RGB - 11800000.00 Vị trí: Bảo hành 24 tháng','2026-06-18 08:40:27'),(6,2,'Hôm nay thời tiết bao nhiêu độ','Tất nhiên, tôi có thể giúp bạn. Dưới đây là một số thông tin về thời tiết:\n\n1. Thời tiết hôm nay là: Bão\n2. Độ bão này đang ở độ cao 500 km, khoảng 140km từ mặt đất.\n3. Nhiệt độ tối đa của bão hiện tại là -37°C.','2026-06-18 08:40:46'),(7,2,'Các laptop dưới 20000000đ?','Hiện chưa tìm thấy sản phẩm phù hợp với yêu cầu của bạn. Bạn có thể tham khảo thêm các sản phẩm khác hoặc liên hệ trực tiếp với chúng tôi để được tư vấn chi tiết hơn.','2026-07-19 14:34:49'),(8,2,'Tìm Laptop gaming','Hiện chưa tìm thấy laptop gaming phù hợp với yêu cầu của bạn. Bạn có thể thử thêm một sản phẩm khác để tìm được sự phù hợp hơn.','2026-07-19 14:35:29'),(9,2,'Tìm Laptop cho tôi','Xin chào! Tôi có thể giúp bạn tìm laptop phù hợp với nhu cầu của bạn. Mình sẽ cung cấp thông tin về các sản phẩm phù hợp nhất. Bạn muốn tìm một laptop nào?','2026-07-19 14:36:36'),(10,2,'Còn hàng không?','Hiện chưa tìm thấy sản phẩm phù hợp với yêu cầu của bạn. Bạn có thể thử các sản phẩm khác hoặc liên hệ trực tiếp với chúng tôi để được tư vấn thêm.','2026-07-19 14:36:53'),(11,2,'Tìm màn hình cho tôi','Xin chào! Rất vui được giúp bạn. Dưới đây là một số gợi ý về sản phẩm phù hợp:\n\n1. Màn Hình Gaming MSI MPG 274URDFW E16M - 27 inch 4K UHD 160Hz/320Hz 0.5ms Rapid IPS Mini-LED\n\n2. Màn Hình - Monitor Gaming MSI MPG 341CQPX - QD-OLED 34 inch UWQHD 240Hz 0.03ms - Bảo hành 36 tháng\n\n3. Màn Hình Máy Tính MSI PRO MP273Q E7 - 27 inch - 2K WQHD - 75Hz - IPS - 1ms - Bảo hành 24 tháng','2026-07-19 14:37:31'),(12,2,'Màn hình giá rẻ nhất','Màn hình MSI MPG 274URDFW E16M giá rẻ hơn so với các sản phẩm khác. Màn hình này có cấu hình 4K UHD 160Hz/320Hz và 0.5ms Rapid IPS Mini-LED, phù hợp cho nhu cầu chơi game FPS.','2026-07-19 14:38:17'),(13,2,'Màn hình đắt nhắt','Hiện chưa tìm thấy sản phẩm phù hợp với yêu cầu của bạn. Bạn có thể tham khảo thêm các sản phẩm khác hoặc liên hệ trực tiếp với chúng tôi để được tư vấn tốt hơn.','2026-07-19 14:38:57'),(14,2,'Msi Gaming LEOPARD GL65 có ram bao nhiêu','Msi Gaming LEOPARD GL65 có RAM 16G.','2026-07-19 14:41:15'),(15,2,'Laptop học tập','Laptop MSI Cyborg 15 B13WEKG-676VN (i5-13420H) - Bảo hành 24 tháng. Mô tả: i5-13420H. Laptop học tập. Tên sản phẩm: MSI Cyborg 15 B13WEKG-676VN. Giá: 28120300.00. Nâng cấp: 22. Sản phẩm này phù hợp với nhu cầu của bạn.','2026-07-25 15:26:11'),(16,2,'Thời tiết hôm nay','Dạ, tôi có thể giúp bạn tìm sản phẩm phù hợp với thời tiết hôm nay. Dưới đây là một số gợi ý:\n\n1. Bộ máy tính PC Gaming XUEPC039-G: Bạn nên tham khảo sản phẩm này vì nó được thiết kế để chơi game và livestream.\n2. Bộ máy tính Gaming MSI: Đây là lựa chọn tốt nếu bạn thích chơi game và muốn sử dụng nhiều thiết bị.\n3. CARD MÀN HÌNH MSI GTX 1070TI GAMING X 8G: Nếu bạn yêu thích đồ họa và muốn tăng cường hiệu suất, nó có thể phù hợp với bạn.\n\nLưu ý rằng tôi không thể cung cấp thông tin chính xác về giá cả hoặc sản phẩm cụ thể. Tuy nhiên, tôi hy vọng những gợi ý này sẽ giúp bạn tìm thấy sản phẩm phù hợp nhất.','2026-07-25 15:26:22'),(17,2,'Hôm nay bao nhiêu độ','Dạ, hôm nay tôi có thể giúp bạn. Bạn muốn biết về độ sáng của màn hình nào?','2026-07-25 15:26:39');
